"""Chunk document schema."""

import json
from typing import Any, Dict, List

from pydantic import BaseModel, Field


class Chunk(BaseModel):
    """Document Chunk including chunk content, chunk metadata."""

    content: str = Field(default="", description="chunk text content")
    seq: int = Field(default=0, description="Chunk sequence number")
    start: int = Field(default=0, description="Chunk start position")
    end: int = Field(description="Chunk end position")
    images: List[Dict[str, Any]] = Field(
        default_factory=list, description="Images in the chunk"
    )

    metadata: Dict[str, Any] = Field(
        default_factory=dict,
        description="metadata fields",
    )

    def to_dict(self, **kwargs: Any) -> Dict[str, Any]:
        """Convert Chunk to dict."""

        data = self.model_dump()
        data.update(kwargs)
        data["class_name"] = self.__class__.__name__
        return data

    def to_json(self, **kwargs: Any) -> str:
        """Convert Chunk to json."""
        data = self.to_dict(**kwargs)
        return json.dumps(data)

    def __hash__(self):
        """Hash function."""
        return hash((self.content,))

    def __eq__(self, other):
        """Equal function."""
        return self.content == other.content

    @classmethod
    def from_dict(cls, data: Dict[str, Any], **kwargs: Any):  # type: ignore
        """Create Chunk from dict."""
        if isinstance(kwargs, dict):
            data.update(kwargs)

        data.pop("class_name", None)
        return cls(**data)

    @classmethod
    def from_json(cls, data_str: str, **kwargs: Any):  # type: ignore
        """Create Chunk from json."""
        data = json.loads(data_str)
        return cls.from_dict(data, **kwargs)


class Document(BaseModel):
    """Document including document content, document metadata."""

    model_config = {"arbitrary_types_allowed": True}

    content: str = Field(default="", description="document text content")
    images: Dict[str, str] = Field(
        default_factory=dict, description="Images in the document"
    )

    chunks: List[Chunk] = Field(default_factory=list, description="document chunks")
    metadata: Dict[str, Any] = Field(
        default_factory=dict,
        description="metadata fields",
    )

    def set_content(self, content: str) -> None:
        """Set document content."""
        self.content = content

    def get_content(self) -> str:
        """Get document content."""
        return self.content

    def is_valid(self) -> bool:
        return self.content != ""

// Package chunker - tokens.go provides language-aware token count approximation.
//
// We avoid pulling in a tokenizer dependency (e.g. tiktoken) and instead use
// per-language chars-per-token ratios derived from common embedding model
// vocabularies. The numbers are conservative — they tend to slightly
// over-estimate token counts so that chunks stay safely under model limits.
package chunker

import (
	"unicode"
	"unicode/utf8"
)

// Language identifiers used by the token estimator and the heuristic splitter.
const (
	LangEnglish = "en"
	LangGerman  = "de"
	LangChinese = "zh"
	LangMixed   = "mixed"
)

// charsPerToken holds approximate chars/token ratios per language.
// Numbers err on the conservative side so estimates over-shoot a little.
var charsPerToken = map[string]float64{
	LangEnglish: 4.0,
	LangGerman:  4.5,
	LangChinese: 1.7,
	LangMixed:   3.0,
}

// ApproxTokenCount returns a conservative token estimate for s in the given
// language. An empty or unknown lang falls back to "mixed".
func ApproxTokenCount(s string, lang string) int {
	if s == "" {
		return 0
	}
	return ApproxTokenCountFromRuneLen(utf8.RuneCountInString(s), lang)
}

// ApproxTokenCountFromRuneLen is the allocation-free variant of
// ApproxTokenCount when the caller has already computed the rune length.
// Use this in hot loops where the same content's rune count would
// otherwise be recomputed multiple times (e.g. preview endpoint emitting
// per-chunk stats).
func ApproxTokenCountFromRuneLen(runeLen int, lang string) int {
	if runeLen <= 0 {
		return 0
	}
	ratio, ok := charsPerToken[lang]
	if !ok {
		ratio = charsPerToken[LangMixed]
	}
	approx := float64(runeLen) / ratio
	if approx < 1 {
		return 1
	}
	return int(approx + 0.5)
}

// DetectLanguage returns a coarse language label by counting CJK runes vs.
// Latin runes. The result is one of LangChinese, LangGerman, LangEnglish or
// LangMixed. Detection is cheap and meant only for heuristic dispatch — it
// is NOT a replacement for proper language identification.
func DetectLanguage(s string) string {
	if s == "" {
		return LangMixed
	}
	var cjk, latin, umlaut int
	for _, r := range s {
		switch {
		case unicode.Is(unicode.Han, r) || unicode.Is(unicode.Hangul, r) || unicode.Is(unicode.Hiragana, r) || unicode.Is(unicode.Katakana, r):
			cjk++
		case isGermanUmlaut(r):
			umlaut++
			latin++
		case (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z'):
			latin++
		}
	}
	total := cjk + latin
	if total == 0 {
		return LangMixed
	}
	cjkRatio := float64(cjk) / float64(total)
	latinRatio := float64(latin) / float64(total)
	// Mixed: meaningful presence of both scripts (>=15% each).
	if cjkRatio >= 0.15 && latinRatio >= 0.15 {
		return LangMixed
	}
	if cjkRatio > 0.3 {
		return LangChinese
	}
	if umlaut > 0 || hasGermanWords(s) {
		return LangGerman
	}
	return LangEnglish
}

func isGermanUmlaut(r rune) bool {
	switch r {
	case 'ä', 'ö', 'ü', 'Ä', 'Ö', 'Ü', 'ß':
		return true
	}
	return false
}

// hasGermanWords does a tiny stop-word check to bias towards "de" when the
// text uses common German function words. Cheap heuristic — false positives
// on borrowed terms are acceptable.
func hasGermanWords(s string) bool {
	const sample = 512
	if len(s) > sample {
		s = s[:sample]
	}
	for _, w := range []string{" der ", " die ", " das ", " und ", " ist ", " nicht ", " mit ", " auf "} {
		if containsLower(s, w) {
			return true
		}
	}
	return false
}

func containsLower(haystack, needle string) bool {
	if len(haystack) < len(needle) {
		return false
	}
	for i := 0; i+len(needle) <= len(haystack); i++ {
		match := true
		for j := 0; j < len(needle); j++ {
			h := haystack[i+j]
			if h >= 'A' && h <= 'Z' {
				h += 'a' - 'A'
			}
			if h != needle[j] {
				match = false
				break
			}
		}
		if match {
			return true
		}
	}
	return false
}

// CharsForTokenLimit converts a token limit into an approximate character
// budget for a given language. Used to size chunks so they fit within an
// embedding model's max-token window with a small safety margin.
func CharsForTokenLimit(tokens int, lang string) int {
	if tokens <= 0 {
		return 0
	}
	ratio, ok := charsPerToken[lang]
	if !ok {
		ratio = charsPerToken[LangMixed]
	}
	// 0.9 safety factor so we under-shoot the model limit instead of overshooting.
	return int(float64(tokens) * ratio * 0.9)
}

type DepmapSearchParams = { limit?: number; query: string };

const CMP_BASE = "https://api.cellmodelpassports.sanger.ac.uk";
const CMP_MODEL_URL = "https://cellmodelpassports.sanger.ac.uk/passports";
const DEFAULT_LIMIT = 5;
const MAX_LIMIT = 20;
const REQUEST_TIMEOUT_MS = 30_000;
const DOCS = [
	"https://depmap.sanger.ac.uk/documentation/api/",
	"https://api.cellmodelpassports.sanger.ac.uk/swagger",
	"https://depmap.org/portal/api/download/files",
];

type RequestResult = {
	endpoint: string;
	payload: unknown;
};

type ParsedQuery =
	| { mode: "dependencies"; gene: string; modelId?: string }
	| { mode: "gene-search"; value: string; exact: boolean }
	| { mode: "model-detail"; value: string }
	| { mode: "model-search"; value: string }
	| { mode: "models"; cancerType?: string; tissue?: string };

function recordValue(value: unknown): Record<string, unknown> {
	return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : {};
}

function arrayValue(value: unknown): unknown[] {
	return Array.isArray(value) ? value : [];
}

function stringValue(value: unknown): string | undefined {
	return typeof value === "string" && value.trim() ? value.trim() : undefined;
}

function idValue(value: unknown): string | undefined {
	if (typeof value === "string" && value.trim()) return value.trim();
	if (typeof value === "number" && Number.isFinite(value)) return String(value);
	return undefined;
}

function numberValue(value: unknown): number | undefined {
	if (typeof value === "number" && Number.isFinite(value)) return value;
	if (typeof value === "string" && value.trim() && Number.isFinite(Number(value))) return Number(value);
	return undefined;
}

function booleanValue(value: unknown): boolean | undefined {
	return typeof value === "boolean" ? value : undefined;
}

function safeLimit(value: number | undefined): number {
	if (!Number.isFinite(value) || value === undefined) return DEFAULT_LIMIT;
	return Math.max(1, Math.min(Math.floor(value), MAX_LIMIT));
}

function cleanQuery(query: string): string {
	const clean = query.trim();
	if (!clean) throw new Error("DepMap search requires a non-empty query.");
	return clean;
}

function compactRecord(record: Record<string, unknown>): Record<string, unknown> {
	return Object.fromEntries(Object.entries(record).filter(([, value]) => {
		if (value === undefined || value === null) return false;
		if (Array.isArray(value)) return value.length > 0;
		if (typeof value === "object") return Object.keys(recordValue(value)).length > 0;
		return true;
	}));
}

function encodePath(value: string): string {
	return encodeURIComponent(value);
}

function cmpUrl(path: string, params?: Record<string, string | number | undefined>): URL {
	const url = new URL(`${CMP_BASE}${path}`);
	for (const [key, value] of Object.entries(params ?? {})) {
		if (value !== undefined) url.searchParams.set(key, String(value));
	}
	return url;
}

function cmpFilter(spec: Array<Record<string, unknown>>): string {
	return JSON.stringify(spec);
}

async function requestJson(path: string, params?: Record<string, string | number | undefined>): Promise<RequestResult> {
	const url = cmpUrl(path, params);
	const controller = new AbortController();
	const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
	try {
		const response = await fetch(url, {
			headers: { accept: "application/vnd.api+json, application/json" },
			signal: controller.signal,
		});
		if (!response.ok) {
			const body = await response.text().catch(() => "");
			throw new Error(`DepMap Cell Model Passports request failed: ${response.status} ${response.statusText}${body ? ` ${body.slice(0, 180)}` : ""}`);
		}
		return { endpoint: url.toString(), payload: await response.json() };
	} finally {
		clearTimeout(timeout);
	}
}

function parseQuery(query: string): ParsedQuery {
	const clean = cleanQuery(query);
	const match = clean.match(/^([a-z][a-z0-9_-]*)\s*:\s*(.+)$/i);
	if (!match) {
		if (/^SIDM\d+$/i.test(clean)) return { mode: "model-detail", value: clean.toUpperCase() };
		return { mode: "model-search", value: clean };
	}
	const key = match[1]!.toLowerCase().replace(/_/g, "-");
	const value = cleanQuery(match[2]!);
	if (key === "model" || key === "model-id" || key === "get-model") return { mode: "model-detail", value };
	if (key === "models" || key === "list-models") return parseModelsQuery(value);
	if (key === "model-search" || key === "search-models") return { mode: "model-search", value };
	if (key === "gene") return { mode: "gene-search", value, exact: true };
	if (key === "genes" || key === "search-genes") return { mode: "gene-search", value, exact: false };
	if (key === "dependencies" || key === "dependency" || key === "crispr" || key === "gene-dependencies") return parseDependencyQuery(value);
	return { mode: "model-search", value: clean };
}

function parseModelsQuery(value: string): ParsedQuery {
	let tissue: string | undefined;
	let cancerType: string | undefined;
	for (const part of value.split(/[;,]/).map((item) => item.trim()).filter(Boolean)) {
		const match = part.match(/^(tissue|cancer[-_ ]?type)\s*=\s*(.+)$/i);
		if (match?.[1]?.toLowerCase().startsWith("tissue")) tissue = match[2]!.trim();
		else if (match) cancerType = match[2]!.trim();
		else tissue = part;
	}
	return { mode: "models", tissue, cancerType };
}

function parseDependencyQuery(value: string): ParsedQuery {
	const atParts = value.split("@").map((part) => part.trim()).filter(Boolean);
	if (atParts.length === 2) return { mode: "dependencies", gene: atParts[0]!, modelId: atParts[1]!.toUpperCase() };
	const inMatch = value.match(/^(.+?)\s+(?:in|model=)\s+(SIDM\d+)$/i);
	if (inMatch) return { mode: "dependencies", gene: inMatch[1]!.trim(), modelId: inMatch[2]!.toUpperCase() };
	return { mode: "dependencies", gene: value.trim() };
}

function modelUrl(modelId: string | undefined): string | undefined {
	return modelId ? `${CMP_MODEL_URL}/${encodeURIComponent(modelId)}` : undefined;
}

function includedByTypeAndId(included: unknown): Map<string, Record<string, unknown>> {
	const map = new Map<string, Record<string, unknown>>();
	for (const item of arrayValue(included)) {
		const record = recordValue(item);
		const type = stringValue(record.type);
		const id = idValue(record.id);
		if (type && id) map.set(`${type}:${id}`, record);
	}
	return map;
}

function relationshipId(record: Record<string, unknown>, name: string): string | undefined {
	const relationship = recordValue(recordValue(record.relationships)[name]);
	const data = recordValue(relationship.data);
	return idValue(data.id);
}

function relationshipManyIds(record: Record<string, unknown>, name: string): string[] {
	const relationship = recordValue(recordValue(record.relationships)[name]);
	return arrayValue(relationship.data).map((item) => stringValue(recordValue(item).id)).filter(Boolean) as string[];
}

function normalizeModel(record: Record<string, unknown>, included?: unknown): Record<string, unknown> {
	const attrs = recordValue(record.attributes);
	const modelId = idValue(record.id);
	const includedMap = includedByTypeAndId(included);
	const sampleId = relationshipId(record, "sample");
	const tissueId = relationshipId(includedMap.get(`sample:${sampleId}`) ?? {}, "tissue");
	const cancerTypeId = relationshipId(includedMap.get(`sample:${sampleId}`) ?? {}, "cancer_type");
	const msiIds = relationshipManyIds(record, "model_msi_status");
	const currentMsi = msiIds
		.map((id) => recordValue(includedMap.get(`model_msi_status:${id}`)))
		.find((item) => booleanValue(recordValue(item.attributes).current));
	const currentMsiAttrs = recordValue(recordValue(currentMsi).attributes);
	return compactRecord({
		modelId,
		names: arrayValue(attrs.names).map(String).sort((a, b) => a.localeCompare(b)),
		modelType: stringValue(attrs.model_type),
		growthProperties: stringValue(attrs.growth_properties),
		modelTreatment: stringValue(attrs.model_treatment),
		tissue: stringValue(recordValue(recordValue(includedMap.get(`tissue:${tissueId}`)).attributes).name),
		cancerType: stringValue(recordValue(recordValue(includedMap.get(`cancer_type:${cancerTypeId}`)).attributes).name),
		sampleId,
		msiStatus: stringValue(currentMsiAttrs.msi_status),
		ploidyWes: numberValue(attrs.ploidy_wes),
		ploidyWgs: numberValue(attrs.ploidy_wgs),
		mutationsPerMb: numberValue(attrs.mutations_per_mb),
		doi: stringValue(attrs.doi),
		pubmedId: stringValue(attrs.pmed),
		dataAvailability: compactRecord({
			mutations: booleanValue(attrs.mutations_available),
			copyNumber: booleanValue(attrs.cnv_available),
			expression: booleanValue(attrs.expression_available),
			rnaSeq: booleanValue(attrs.rnaseq_available),
			crisprKo: booleanValue(attrs.crispr_ko_available),
			drugs: booleanValue(attrs.drugs_available),
			fusions: booleanValue(attrs.fusions_available),
			methylation: booleanValue(attrs.methylation_available),
			proteomics: booleanValue(attrs.proteomics_available),
			commercial: booleanValue(attrs.commercial_available),
		}),
		url: modelUrl(modelId),
	});
}

function normalizeModelRow(record: Record<string, unknown>): Record<string, unknown> {
	const attrs = recordValue(record.attributes);
	const modelId = idValue(record.id);
	return compactRecord({
		modelId,
		names: arrayValue(attrs.names).map(String).sort((a, b) => a.localeCompare(b)),
		modelType: stringValue(attrs.model_type),
		growthProperties: stringValue(attrs.growth_properties),
		crisprKoAvailable: booleanValue(attrs.crispr_ko_available),
		rnaSeqAvailable: booleanValue(attrs.rnaseq_available),
		mutationsAvailable: booleanValue(attrs.mutations_available),
		url: modelUrl(modelId),
	});
}

function normalizeGene(record: Record<string, unknown>): Record<string, unknown> {
	const attrs = recordValue(record.attributes);
	const geneId = idValue(record.id);
	return compactRecord({
		geneId,
		symbol: stringValue(attrs.symbol),
		hgncId: stringValue(attrs.hgnc_id),
		hgncStatus: stringValue(attrs.hgnc_status),
		location: stringValue(attrs.location),
		cancerDriver: booleanValue(attrs.cancer_driver),
		tumourSuppressor: booleanValue(attrs.tumour_suppressor),
		methodOfAction: stringValue(attrs.method_of_action),
		inYusaLibrary: booleanValue(attrs.in_yusa_lib),
		url: geneId ? `${CMP_BASE}/genes/${encodeURIComponent(geneId)}` : undefined,
	});
}

function normalizeDependency(record: Record<string, unknown>): Record<string, unknown> {
	const attrs = recordValue(record.attributes);
	return compactRecord({
		geneId: relationshipId(record, "gene"),
		modelId: relationshipId(record, "model"),
		source: stringValue(attrs.source),
		bayesFactor: numberValue(attrs.bf),
		scaledBayesFactor: numberValue(attrs.bf_scaled),
		cleanFoldChange: numberValue(attrs.fc_clean),
		quantileNormalizedCleanFoldChange: numberValue(attrs.fc_clean_qn),
		mageckFdr: numberValue(attrs.mageck_fdr),
		qcPass: booleanValue(attrs.qc_pass),
	});
}

async function searchModels(params: DepmapSearchParams, parsed: Extract<ParsedQuery, { mode: "models" }>): Promise<Record<string, unknown>> {
	const limit = safeLimit(params.limit);
	const filter: Array<Record<string, unknown>> = [];
	if (parsed.tissue) {
		filter.push({ name: "sample", op: "has", val: { name: "tissue", op: "has", val: { name: "name", op: "eq", val: parsed.tissue } } });
	}
	if (parsed.cancerType) {
		filter.push({ name: "sample", op: "has", val: { name: "cancer_type", op: "has", val: { name: "name", op: "eq", val: parsed.cancerType } } });
	}
	const result = await requestJson("/models", {
		...(filter.length ? { filter: cmpFilter(filter) } : {}),
		"page[size]": limit,
		"page[number]": 1,
	});
	const payload = recordValue(result.payload);
	const results = arrayValue(payload.data).map((item) => normalizeModelRow(recordValue(item)));
	return {
		schema: "feynman.scienceDatabaseSearch.v1",
		source: "depmap",
		query: params.query,
		searchMode: "model-list",
		tissue: parsed.tissue,
		cancerType: parsed.cancerType,
		totalCount: numberValue(recordValue(payload.meta).count) ?? results.length,
		returned: results.length,
		results,
		provenance: { docs: DOCS, endpoints: [result.endpoint] },
	};
}

async function searchModelName(params: DepmapSearchParams, value: string): Promise<Record<string, unknown>> {
	const limit = safeLimit(params.limit);
	const result = await requestJson(`/search/${encodePath(value)}`);
	const payload = recordValue(result.payload);
	const rows = arrayValue(payload.data)
		.map((item) => recordValue(item))
		.filter((item) => stringValue(item.type) === "model")
		.slice(0, limit)
		.map(normalizeModelRow);
	return {
		schema: "feynman.scienceDatabaseSearch.v1",
		source: "depmap",
		query: params.query,
		searchMode: "model-search",
		totalCount: numberValue(recordValue(payload.meta).count) ?? rows.length,
		returned: rows.length,
		results: rows,
		provenance: { docs: DOCS, endpoints: [result.endpoint] },
	};
}

async function getModel(params: DepmapSearchParams, value: string): Promise<Record<string, unknown>> {
	const endpoints: string[] = [];
	let record: Record<string, unknown> | undefined;
	let included: unknown;
	if (/^SIDM\d+$/i.test(value)) {
		const result = await requestJson(`/models/${encodePath(value.toUpperCase())}`, { include: "sample.tissue,sample.cancer_type,model_msi_status" });
		endpoints.push(result.endpoint);
		const payload = recordValue(result.payload);
		record = recordValue(payload.data);
		included = payload.included;
	} else {
		const result = await requestJson("/models", {
			filter: cmpFilter([{ name: "names", op: "any", val: value }]),
			include: "sample.tissue,sample.cancer_type,model_msi_status",
			"page[size]": 5,
		});
		endpoints.push(result.endpoint);
		const payload = recordValue(result.payload);
		const data = arrayValue(payload.data);
		record = recordValue(data[0]);
		included = payload.included;
	}
	const results = record && Object.keys(record).length ? [normalizeModel(record, included)] : [];
	return {
		schema: "feynman.scienceDatabaseSearch.v1",
		source: "depmap",
		query: params.query,
		searchMode: "model-detail",
		totalCount: results.length,
		returned: results.length,
		results,
		provenance: { docs: DOCS, endpoints },
	};
}

async function searchGenes(params: DepmapSearchParams, parsed: Extract<ParsedQuery, { mode: "gene-search" }>): Promise<Record<string, unknown>> {
	const limit = safeLimit(params.limit);
	const result = await requestJson("/genes", {
		filter: cmpFilter([{ name: "symbol", op: parsed.exact ? "eq" : "ilike", val: parsed.exact ? parsed.value : `%${parsed.value}%` }]),
		"page[size]": limit,
		"page[number]": 1,
	});
	const payload = recordValue(result.payload);
	const results = arrayValue(payload.data).map((item) => normalizeGene(recordValue(item)));
	return {
		schema: "feynman.scienceDatabaseSearch.v1",
		source: "depmap",
		query: params.query,
		searchMode: parsed.exact ? "exact-gene" : "gene-search",
		totalCount: numberValue(recordValue(payload.meta).count) ?? results.length,
		returned: results.length,
		results,
		provenance: { docs: DOCS, endpoints: [result.endpoint] },
	};
}

async function resolveGene(symbol: string): Promise<{ endpoint: string; gene?: Record<string, unknown>; geneId?: string }> {
	const result = await requestJson("/genes", {
		filter: cmpFilter([{ name: "symbol", op: "eq", val: symbol }]),
		"page[size]": 5,
	});
	const payload = recordValue(result.payload);
	const record = recordValue(arrayValue(payload.data)[0]);
	const gene = Object.keys(record).length ? normalizeGene(record) : undefined;
	return { endpoint: result.endpoint, gene, geneId: idValue(record.id) };
}

async function searchDependencies(params: DepmapSearchParams, parsed: Extract<ParsedQuery, { mode: "dependencies" }>): Promise<Record<string, unknown>> {
	const limit = safeLimit(params.limit);
	const endpoints: string[] = [];
	const geneResult = await resolveGene(parsed.gene);
	endpoints.push(geneResult.endpoint);
	if (!geneResult.geneId) {
		return {
			schema: "feynman.scienceDatabaseSearch.v1",
			source: "depmap",
			query: params.query,
			searchMode: "crispr-dependencies",
			gene: parsed.gene,
			modelId: parsed.modelId,
			totalCount: 0,
			returned: 0,
			results: [],
			warnings: [`No Cell Model Passports gene record found for ${parsed.gene}.`],
			provenance: { docs: DOCS, endpoints },
		};
	}
	const filter = parsed.modelId
		? { filter: cmpFilter([{ name: "model", op: "has", val: { name: "id", op: "eq", val: parsed.modelId } }]) }
		: {};
	const result = await requestJson(`/genes/${encodePath(geneResult.geneId)}/datasets/crispr_ko`, {
		...filter,
		"page[size]": limit,
		"page[number]": 1,
	});
	endpoints.push(result.endpoint);
	const payload = recordValue(result.payload);
	const results = arrayValue(payload.data).map((item) => normalizeDependency(recordValue(item)));
	return {
		schema: "feynman.scienceDatabaseSearch.v1",
		source: "depmap",
		query: params.query,
		searchMode: "crispr-dependencies",
		gene: geneResult.gene,
		modelId: parsed.modelId,
		totalCount: numberValue(recordValue(payload.meta).count) ?? results.length,
		returned: results.length,
		results,
		provenance: { docs: DOCS, endpoints },
	};
}

export async function searchDepmap(params: DepmapSearchParams): Promise<Record<string, unknown>> {
	const parsed = parseQuery(params.query);
	if (parsed.mode === "models") return searchModels(params, parsed);
	if (parsed.mode === "model-detail") return getModel(params, parsed.value);
	if (parsed.mode === "gene-search") return searchGenes(params, parsed);
	if (parsed.mode === "dependencies") return searchDependencies(params, parsed);
	return searchModelName(params, parsed.value);
}

import { existsSync, readFileSync } from "node:fs";

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";

import { migratedWorkbenchDataPath } from "../../src/workbench/data-root.js";

type WorkbenchSettings = {
	allowedDomains?: Array<{ domain?: string; id?: string }>;
	computeHosts?: Array<{
		guidance?: string;
		host?: string;
		id?: string;
		name?: string;
		port?: string;
		scheduler?: string;
		scratchRoot?: string;
		user?: string;
	}>;
	credentialRefs?: Array<{
		description?: string;
		envVar?: string;
		id?: string;
		name?: string;
		provider?: string;
	}>;
	customConnectors?: Array<{
		assignedSpecialists?: string[] | string;
		clientId?: string;
		command?: string;
		description?: string;
		excludedTools?: string[] | string;
		headersHelper?: string;
		id?: string;
		name?: string;
		oauthServerUrl?: string;
		scopes?: string;
		skipApprovals?: boolean;
		transport?: string;
		url?: string;
	}>;
	memoryCategories?: Array<{
		autoRecall?: boolean;
		guidance?: string;
		id?: string;
		name?: string;
	}>;
	permissionGrants?: Array<{
		decision?: string;
		description?: string;
		id?: string;
		name?: string;
		scope?: string;
	}>;
};

function settingsPath(cwd: string): string {
	return migratedWorkbenchDataPath(cwd, "settings.json");
}

function readSettings(cwd: string): WorkbenchSettings {
	const path = settingsPath(cwd);
	if (!existsSync(path)) return {};
	try {
		const parsed = JSON.parse(readFileSync(path, "utf8")) as unknown;
		return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed as WorkbenchSettings : {};
	} catch {
		return {};
	}
}

function stringValue(value: unknown): string | undefined {
	return typeof value === "string" && value.trim() ? value.trim() : undefined;
}

function stringListValue(value: unknown): string[] {
	const rawItems = Array.isArray(value)
		? value.flatMap((item) => typeof item === "string" ? item.split(/[,\n]/) : [])
		: typeof value === "string"
			? value.split(/[,\n]/)
			: [];
	const seen = new Set<string>();
	const items: string[] = [];
	for (const rawItem of rawItems) {
		const item = rawItem.trim();
		if (!item || seen.has(item)) continue;
		seen.add(item);
		items.push(item);
	}
	return items;
}

function credentialStatus(envVar: string | undefined): "missing" | "present" {
	return envVar && process.env[envVar]?.trim() ? "present" : "missing";
}

function sanitizeWorkbenchContext(cwd: string, includeDiagnostics: boolean | undefined): Record<string, unknown> {
	const settings = readSettings(cwd);
	const customConnectors = (settings.customConnectors ?? []).flatMap((connector) => {
		const name = stringValue(connector.name);
		if (!name) return [];
		const transport = stringValue(connector.transport) ?? "streamable_http";
		const oauth = Boolean(connector.oauthServerUrl || connector.clientId || connector.scopes);
		const headers = Boolean(connector.headersHelper);
		const assignedSpecialists = stringListValue(connector.assignedSpecialists);
		const excludedTools = stringListValue(connector.excludedTools);
		return [{
			id: stringValue(connector.id) ?? name,
			name,
			description: stringValue(connector.description),
			assignedSpecialists,
			excludedTools,
			transport,
			target: transport === "local" ? stringValue(connector.command) : stringValue(connector.url),
			auth: oauth && headers ? "oauth-and-headers-helper" : oauth ? "oauth" : headers ? "headers-helper" : "none",
			scopes: stringValue(connector.scopes),
			skipApprovals: connector.skipApprovals === true,
		}];
	});
	const credentialRefs = (settings.credentialRefs ?? []).flatMap((credential) => {
		const envVar = stringValue(credential.envVar);
		const name = stringValue(credential.name);
		const provider = stringValue(credential.provider);
		if (!envVar || !name || !provider) return [];
		return [{
			id: stringValue(credential.id) ?? name,
			name,
			provider,
			envVar,
			status: credentialStatus(envVar),
			description: stringValue(credential.description),
		}];
	});
	const context = {
		schema: "feynman.workbenchContext.v1",
		capturedAt: new Date().toISOString(),
		workspace: cwd,
		customConnectors,
		credentialRefs,
		permissionGrants: (settings.permissionGrants ?? []).map((grant) => ({
			id: stringValue(grant.id) ?? stringValue(grant.name) ?? "grant",
			name: stringValue(grant.name),
			scope: stringValue(grant.scope),
			decision: stringValue(grant.decision) ?? "ask",
			description: stringValue(grant.description),
		})),
		allowedDomains: (settings.allowedDomains ?? []).map((domain) => stringValue(domain.domain)).filter(Boolean),
		computeHosts: (settings.computeHosts ?? []).map((host) => ({
			id: stringValue(host.id) ?? stringValue(host.name) ?? "host",
			name: stringValue(host.name),
			target: [
				host.user ? `${host.user}@${host.host}` : stringValue(host.host),
				host.port ? `port ${host.port}` : undefined,
			].filter(Boolean).join(" "),
			scheduler: stringValue(host.scheduler),
			scratchRoot: stringValue(host.scratchRoot),
			guidance: stringValue(host.guidance),
		})),
		modelEndpoints: [{
			id: "nvidia-bionemo",
			name: "NVIDIA BioNeMo NIM",
			provider: "nvidia-bionemo",
			models: ["esmfold", "alphafold2"],
			defaultEndpoint: "https://health.api.nvidia.com/v1/biology/nvidia/esmfold",
			credentialEnvVar: "NVIDIA_API_KEY",
			status: credentialStatus("NVIDIA_API_KEY"),
			tool: "feynman_model_endpoint_call",
			description: "Hosted ESMFold requires NVIDIA_API_KEY; self-hosted AlphaFold2 NIM can be called with endpointUrl.",
		}],
		memoryCategories: (settings.memoryCategories ?? []).map((category) => ({
			id: stringValue(category.id) ?? stringValue(category.name) ?? "memory",
			name: stringValue(category.name),
			guidance: stringValue(category.guidance),
			autoRecall: category.autoRecall !== false,
		})),
		...(includeDiagnostics ? {
			diagnostics: [
				"Credential values are not returned.",
				"Streamable HTTP, SSE, and local command custom MCP connectors can be discovered with feynman_connector_tools and called through feynman_connector_call.",
				"Scientific model endpoints can be called with feynman_model_endpoint_call and save output artifacts under outputs/model-endpoints.",
				"Connector assignedSpecialists and excludedTools are returned as policy metadata for specialist-scoped chat.",
				"Deny grants are unavailable; ask grants create pending permission requests before execution.",
			],
		} : {}),
	};
	return context;
}

export function registerWorkbenchContextTool(pi: ExtensionAPI): void {
	pi.registerTool({
		name: "feynman_workbench_context",
		label: "Feynman Workbench Context",
		description:
			"Inspect sanitized in-app Feynman science workbench resources: custom connectors, credential refs, permission grants, allowed domains, compute hosts, model endpoints, and memory categories. Never returns secret values.",
		promptSnippet: "Inspect configured Feynman workbench resources and policies without exposing secret values.",
		promptGuidelines: [
			"Use feynman_workbench_context when a workbench chat needs to know which custom connectors, credential refs, grants, compute hosts, model endpoints, allowed domains, or memory categories are configured.",
			"Use feynman_connector_tools and feynman_connector_call for Streamable HTTP, SSE, or local command connector discovery and execution.",
			"Use feynman_model_endpoint_call for hosted ESMFold or self-hosted AlphaFold2 NIM inference calls.",
			"Respect connector assignedSpecialists and excludedTools when deciding which connector tools are available in a specialist chat.",
			"Treat credential values as unavailable; use only the env var names and present/missing status.",
			"Treat deny grants as unavailable and ask grants as requiring explicit user confirmation before use.",
		],
		parameters: Type.Object({
			includeDiagnostics: Type.Optional(Type.Boolean({ description: "Include runtime diagnostics and bridge limitations." })),
		}),
		async execute(_toolCallId, params) {
			const result = sanitizeWorkbenchContext(process.cwd(), params.includeDiagnostics);
			return {
				content: [{ type: "text", text: JSON.stringify(result, null, 2) }],
				details: result,
			};
		},
	});
}

import os
import glob
import config
from pathlib import Path
from langchain_text_splitters import MarkdownHeaderTextSplitter, RecursiveCharacterTextSplitter

class DocumentChunker:
    def __init__(self):
        if config.MIN_PARENT_SIZE <= 0 or config.MAX_PARENT_SIZE < config.MIN_PARENT_SIZE:
            raise ValueError("Parent chunk sizes must be positive and MIN_PARENT_SIZE <= MAX_PARENT_SIZE.")
        if not 0 <= config.CHILD_CHUNK_OVERLAP < config.CHILD_CHUNK_SIZE:
            raise ValueError("CHILD_CHUNK_OVERLAP must be smaller than CHILD_CHUNK_SIZE.")
        if config.CHILD_CHUNK_OVERLAP >= config.MAX_PARENT_SIZE:
            raise ValueError("CHILD_CHUNK_OVERLAP must be smaller than MAX_PARENT_SIZE.")

        self.__parent_splitter = MarkdownHeaderTextSplitter(
            headers_to_split_on=config.HEADERS_TO_SPLIT_ON, 
            strip_headers=False
        )
        self.__child_splitter = RecursiveCharacterTextSplitter(
            chunk_size=config.CHILD_CHUNK_SIZE, 
            chunk_overlap=config.CHILD_CHUNK_OVERLAP
        )
        self.__min_parent_size = config.MIN_PARENT_SIZE
        self.__max_parent_size = config.MAX_PARENT_SIZE

    @staticmethod
    def __merge_metadata(target, source, prepend=False):
        for key, value in source.items():
            if key not in target:
                target[key] = value
            else:
                first, second = (value, target[key]) if prepend else (target[key], value)
                values = [
                    item.strip()
                    for raw in (first, second)
                    for item in str(raw).split(" -> ")
                    if item.strip()
                ]
                target[key] = " -> ".join(dict.fromkeys(values))

    def create_chunks(self, path_dir=config.MARKDOWN_DIR):
        all_parent_chunks, all_child_chunks = [], []

        for doc_path_str in sorted(glob.glob(os.path.join(path_dir, "*.md"))):
            doc_path = Path(doc_path_str)
            parent_chunks, child_chunks = self.create_chunks_single(doc_path)
            all_parent_chunks.extend(parent_chunks)
            all_child_chunks.extend(child_chunks)

        return all_parent_chunks, all_child_chunks

    def create_chunks_single(self, md_path, source_name=None):
        doc_path = Path(md_path)
        source_name = source_name or f"{doc_path.stem}.pdf"

        with open(doc_path, "r", encoding="utf-8") as f:
            parent_chunks = self.__parent_splitter.split_text(f.read())

        merged_parents = self.__merge_small_parents(parent_chunks)
        split_parents = self.__split_large_parents(merged_parents)
        cleaned_parents = self.__clean_small_chunks(split_parents)
        if any(len(chunk.page_content) > self.__max_parent_size for chunk in cleaned_parents):
            raise ValueError("Parent chunking produced a chunk larger than MAX_PARENT_SIZE.")

        all_parent_chunks, all_child_chunks = [], []
        self.__create_child_chunks(
            all_parent_chunks,
            all_child_chunks,
            cleaned_parents,
            doc_path,
            source_name,
        )
        return all_parent_chunks, all_child_chunks

    def __merge_small_parents(self, chunks):
        if not chunks:
            return []

        merged, current = [], None

        for chunk in chunks:
            if current is None:
                current = chunk
            else:
                current.page_content += "\n\n" + chunk.page_content
                self.__merge_metadata(current.metadata, chunk.metadata)

            if len(current.page_content) >= self.__min_parent_size:
                merged.append(current)
                current = None

        if current:
            if merged:
                merged[-1].page_content += "\n\n" + current.page_content
                self.__merge_metadata(merged[-1].metadata, current.metadata)
            else:
                merged.append(current)

        return merged

    def __split_large_parents(self, chunks):
        split_chunks = []

        for chunk in chunks:
            if len(chunk.page_content) <= self.__max_parent_size:
                split_chunks.append(chunk)
            else:
                splitter = RecursiveCharacterTextSplitter(
                    chunk_size=self.__max_parent_size,
                    chunk_overlap=config.CHILD_CHUNK_OVERLAP
                )
                sub_chunks = splitter.split_documents([chunk])
                split_chunks.extend(sub_chunks)

        return split_chunks

    def __rebalance_pair(self, first, second):
        combined = first.page_content.rstrip() + "\n\n" + second.page_content.lstrip()
        lower = max(1, len(combined) - self.__max_parent_size)
        upper = min(self.__max_parent_size, len(combined) - 1)
        if len(combined) >= 2 * self.__min_parent_size:
            lower = max(lower, self.__min_parent_size)
            upper = min(upper, len(combined) - self.__min_parent_size)
        preferred = min(max(len(combined) // 2, lower), upper)

        split_at = preferred
        for separator in ("\n\n", "\n", " "):
            before = combined.rfind(separator, lower, preferred + 1)
            after = combined.find(separator, preferred, upper + 1)
            if before >= lower:
                split_at = before
                break
            if after != -1:
                split_at = after
                break

        left_text = combined[:split_at].rstrip()
        right_text = combined[split_at:].lstrip()
        if len(combined) >= 2 * self.__min_parent_size and (
            len(left_text) < self.__min_parent_size
            or len(right_text) < self.__min_parent_size
        ):
            split_at = preferred
            left_text, right_text = combined[:split_at], combined[split_at:]
        if not left_text or not right_text:
            return first, second

        metadata = dict(first.metadata)
        self.__merge_metadata(metadata, second.metadata)
        first.page_content, first.metadata = left_text, dict(metadata)
        second.page_content, second.metadata = right_text, dict(metadata)
        return first, second

    def __clean_small_chunks(self, chunks):
        cleaned = []

        for i, chunk in enumerate(chunks):
            if len(chunk.page_content) < self.__min_parent_size:
                if cleaned and len(cleaned[-1].page_content) + 2 + len(chunk.page_content) <= self.__max_parent_size:
                    cleaned[-1].page_content += "\n\n" + chunk.page_content
                    self.__merge_metadata(cleaned[-1].metadata, chunk.metadata)
                elif (
                    i < len(chunks) - 1
                    and len(chunk.page_content) + 2 + len(chunks[i + 1].page_content) <= self.__max_parent_size
                ):
                    chunks[i + 1].page_content = chunk.page_content + "\n\n" + chunks[i + 1].page_content
                    self.__merge_metadata(chunks[i + 1].metadata, chunk.metadata, prepend=True)
                else:
                    cleaned.append(chunk)
            else:
                cleaned.append(chunk)

        for i, chunk in enumerate(cleaned):
            if len(chunk.page_content) >= self.__min_parent_size or len(cleaned) == 1:
                continue
            if i < len(cleaned) - 1:
                cleaned[i], cleaned[i + 1] = self.__rebalance_pair(chunk, cleaned[i + 1])
            else:
                cleaned[i - 1], cleaned[i] = self.__rebalance_pair(cleaned[i - 1], chunk)

        return cleaned

    def __create_child_chunks(self, all_parent_pairs, all_child_chunks, parent_chunks, doc_path, source_name):
        for i, p_chunk in enumerate(parent_chunks):
            parent_id = f"{doc_path.stem}_p{i}"
            p_chunk.metadata.update({"source": source_name, "parent_id": parent_id})

            all_parent_pairs.append((parent_id, p_chunk))
            all_child_chunks.extend(self.__child_splitter.split_documents([p_chunk]))

from pathlib import Path
import shutil
import config
from utils import pdfs_to_markdowns, clear_directory_contents

class DocumentManager:

    def __init__(self, rag_system):
        self.rag_system = rag_system
        self.markdown_dir = Path(config.MARKDOWN_DIR)
        self.markdown_dir.mkdir(parents=True, exist_ok=True)

    def add_documents(self, document_paths, progress_callback=None):
        if not document_paths:
            return 0, 0

        document_paths = [document_paths] if isinstance(document_paths, str) else document_paths
        document_paths = [p for p in document_paths if p and Path(p).suffix.lower() in [".pdf", ".md"]]

        if not document_paths:
            return 0, 0

        added = 0
        skipped = 0

        for i, doc_path in enumerate(document_paths):
            if progress_callback:
                progress_callback((i + 1) / len(document_paths), f"Processing {Path(doc_path).name}")

            source_path = Path(doc_path)
            doc_name = source_path.stem
            md_path = self.markdown_dir / f"{doc_name}.md"

            if md_path.exists():
                skipped += 1
                continue

            parent_ids = []
            try:
                if source_path.suffix.lower() == ".md":
                    shutil.copy(source_path, md_path)
                else:
                    pdfs_to_markdowns(str(source_path), overwrite=False)
                parent_chunks, child_chunks = self.rag_system.chunker.create_chunks_single(
                    md_path,
                    source_name=source_path.name,
                )

                if not child_chunks:
                    raise ValueError("No child chunks were created.")

                parent_ids = [parent_id for parent_id, _ in parent_chunks]
                self.rag_system.parent_store.save_many(parent_chunks)
                collection = self.rag_system.vector_db.get_collection(self.rag_system.collection_name)
                collection.add_documents(child_chunks)

                added += 1

            except Exception as e:
                self.rag_system.parent_store.delete_many(parent_ids)
                if md_path.exists():
                    md_path.unlink()
                print(f"Error processing {doc_path}: {e}")
                skipped += 1

        return added, skipped

    def get_markdown_files(self):
        sources = self.rag_system.parent_store.list_sources()
        if sources:
            return sources
        return sorted(p.name for p in self.markdown_dir.glob("*.md"))

    def clear_all(self):
        self.markdown_dir.mkdir(parents=True, exist_ok=True)
        self.rag_system.vector_db.delete_collection(self.rag_system.collection_name)

        clear_directory_contents(self.markdown_dir)
        self.rag_system.parent_store.clear_store()

        self.rag_system.vector_db.create_collection(self.rag_system.collection_name)
